"""Bundled sample datasets (FR-ING-06, D-05, D-14; DEC-041).

The licenses of the five datasets the PRD names (Titanic, House Prices, Adult Income, Telco Churn,
Credit Default) and of the OpenML multiclass candidates could not be verified in the build
environment (Q-03). FR-ING-06 and the P16 prompt allow an alternative, so each sample is a
**synthetic** dataset generated by this module from a fixed seed. Each one copies the column
*structure* of the public dataset it is named after, but it contains no record from that
dataset. The data is generated by this repository and licensed like the code (MIT). The owner can
swap in a verified real dataset later without changing the UI.

Samples are generated on first use into `<data_dir>/samples/` (never committed, CLAUDE.md §8).
The same seed and the pinned numpy give the same bytes, which `sha256` in the catalog records.
"""

from __future__ import annotations

import hashlib
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path

import numpy as np
import pandas as pd

from tabpilot.schemas import Task

LICENSE_NOTE = ("Synthetic data generated by TabPilot (MIT license). It copies the column "
                "structure of the public dataset it is named after but contains none of its "
                "records.")  # fmt: skip
EPOCH = np.datetime64("2019-01-01")


@dataclass(frozen=True)
class Sample:
    """One bundled sample: its card text, pre-selected target and license note (FR-ING-06)."""

    sample_id: str
    title: str
    description: str
    target: str
    task: Task
    rows: int
    license: str = LICENSE_NOTE

    @property
    def filename(self) -> str:
        return f"{self.sample_id}.csv"


def _sigmoid(x: np.ndarray) -> np.ndarray:
    out: np.ndarray = 1.0 / (1.0 + np.exp(-x))
    return out


def _mask(rng: np.random.Generator, values: np.ndarray, share: float) -> pd.Series:
    """`values` with a seeded share set to missing."""
    out = pd.Series(values, dtype="object")
    out[rng.random(len(values)) < share] = None
    return out


def passengers(rng: np.random.Generator, n: int) -> pd.DataFrame:
    pclass = rng.choice([1, 2, 3], n, p=[0.24, 0.21, 0.55])
    sex = rng.choice(["female", "male"], n, p=[0.35, 0.65])
    age = np.clip(rng.normal(30, 14, n), 0.5, 80).round(1)
    sibsp = rng.choice([0, 1, 2, 3, 4], n, p=[0.68, 0.23, 0.04, 0.03, 0.02])
    parch = rng.choice([0, 1, 2, 3], n, p=[0.76, 0.13, 0.09, 0.02])
    fare = np.round(np.exp(rng.normal(3.6 - 0.6 * (pclass - 1), 0.6, n)), 2)
    embarked = rng.choice(["S", "C", "Q"], n, p=[0.72, 0.19, 0.09])
    deck = np.where(pclass == 1, rng.choice(list("ABCDE"), n), rng.choice(list("DEFG"), n))
    logit = 1.2 * (sex == "female") * 2 - 0.9 * (pclass - 2) - 0.02 * (age - 30) - 0.3 * sibsp
    survived = (rng.random(n) < _sigmoid(logit - 0.9)).astype(int)
    return pd.DataFrame({
        "PassengerId": np.arange(1, n + 1), "Pclass": pclass, "Sex": sex,
        "Age": _mask(rng, age, 0.2), "SibSp": sibsp, "Parch": parch, "Fare": fare,
        "Cabin Deck": _mask(rng, deck, 0.75), "Embarked": _mask(rng, embarked, 0.003),
        "Survived": survived,
    })  # fmt: skip


def house_prices(rng: np.random.Generator, n: int) -> pd.DataFrame:
    hoods = [f"district_{i:02d}" for i in range(1, 19)]
    hood = rng.choice(hoods, n)
    hood_effect = {h: rng.normal(0, 0.18) for h in hoods}
    quality = rng.integers(1, 11, n)
    living = np.round(np.exp(rng.normal(7.3, 0.33, n)))
    lot = np.round(np.exp(rng.normal(9.1, 0.45, n)))
    year = rng.integers(1900, 2011, n)
    beds = np.clip(np.round(living / 550 + rng.normal(0, 0.8, n)), 1, 7).astype(int)
    baths = np.clip(np.round(beds * 0.6 + rng.normal(0, 0.5, n) * 2) / 2, 1, 5)
    garage = rng.choice([0, 1, 2, 3], n, p=[0.06, 0.26, 0.56, 0.12])
    sold = (EPOCH + rng.integers(0, 4 * 365, n).astype("timedelta64[D]")).astype(str)
    log_price = (10.6 + 0.09 * quality + 0.55 * np.log(living / 1500) + 0.08 * np.log(lot / 9000)
                 + 0.003 * (year - 1970) + 0.05 * garage + np.vectorize(hood_effect.get)(hood)
                 + rng.normal(0, 0.12, n))  # fmt: skip
    return pd.DataFrame({
        "Id": np.arange(1, n + 1), "Neighborhood": hood, "OverallQual": quality,
        "GrLivArea": living.astype(int), "LotArea": lot.astype(int), "YearBuilt": year,
        "Bedrooms": beds, "FullBath": baths, "GarageCars": garage,
        "PoolArea": np.where(rng.random(n) < 0.01, rng.integers(300, 700, n), 0),
        "SaleDate": sold, "SalePrice": np.round(np.exp(log_price), -2).astype(int),
    })  # fmt: skip


def adult_income(rng: np.random.Generator, n: int) -> pd.DataFrame:
    edu = ["HS-grad", "Some-college", "Bachelors", "Masters", "Assoc", "11th", "Doctorate"]
    edu_years = {"11th": 7, "HS-grad": 9, "Some-college": 10, "Assoc": 11, "Bachelors": 13,
                 "Masters": 14, "Doctorate": 16}  # fmt: skip
    education = rng.choice(edu, n, p=[0.33, 0.23, 0.17, 0.06, 0.08, 0.11, 0.02])
    years = np.vectorize(edu_years.get)(education)
    age = rng.integers(17, 80, n)
    hours = np.clip(np.round(rng.normal(40, 11, n)), 1, 99).astype(int)
    occupation = rng.choice(
        [
            "Prof-specialty",
            "Craft-repair",
            "Exec-managerial",
            "Sales",
            "Adm-clerical",
            "Other-service",
            "Machine-op",
            "Transport",
        ],
        n,
    )
    marital = rng.choice(["Married", "Never-married", "Divorced", "Widowed"], n,
                         p=[0.47, 0.33, 0.14, 0.06])  # fmt: skip
    sex = rng.choice(["Male", "Female"], n, p=[0.67, 0.33])
    gain = np.where(rng.random(n) < 0.08, np.round(np.exp(rng.normal(8.5, 1.0, n))), 0)
    region = rng.choice(["North-America", "Latin-America", "Europe", "Asia", "Other"], n,
                        p=[0.9, 0.04, 0.02, 0.03, 0.01])  # fmt: skip
    logit = (0.35 * (years - 10) + 0.04 * (np.minimum(age, 60) - 38) + 0.03 * (hours - 40)
             + 1.3 * (marital == "Married") + 0.6 * (occupation == "Exec-managerial")
             + 0.00015 * gain - 1.6)  # fmt: skip
    over = rng.random(n) < _sigmoid(logit)
    return pd.DataFrame({
        "age": age, "education": education, "education-num": years,
        "occupation": _mask(rng, occupation, 0.05), "marital-status": marital, "sex": sex,
        "hours-per-week": hours, "capital-gain": gain.astype(int), "native-region": region,
        "income": np.where(over, ">50K", "<=50K"),
    })  # fmt: skip


def telco_churn(rng: np.random.Generator, n: int) -> pd.DataFrame:
    contract = rng.choice(["Month-to-month", "One year", "Two year"], n, p=[0.55, 0.21, 0.24])
    tenure = np.where(contract == "Month-to-month", rng.integers(0, 40, n), rng.integers(6, 73, n))
    internet = rng.choice(["Fiber optic", "DSL", "No"], n, p=[0.44, 0.34, 0.22])
    monthly = np.round(np.where(internet == "No", rng.uniform(18, 26, n),
                                rng.uniform(45, 115, n)), 2)  # fmt: skip
    total = np.round(monthly * tenure * rng.uniform(0.95, 1.05, n), 2)
    total_text = np.where(tenure == 0, " ", total.astype(str))  # blank totals, as in many exports
    payment = rng.choice(["Electronic check", "Mailed check", "Bank transfer", "Credit card"], n)
    support = rng.choice(["Yes", "No"], n, p=[0.3, 0.7])
    senior = (rng.random(n) < 0.16).astype(int)
    logit = (1.4 * (contract == "Month-to-month") - 0.035 * tenure
             + 0.8 * (internet == "Fiber optic") + 0.5 * (payment == "Electronic check")
             - 0.6 * (support == "Yes") + 0.3 * senior
             - 1.3)  # fmt: skip
    churn = rng.random(n) < _sigmoid(logit)
    ids = [
        f"{a:04d}-{b}"
        for a, b in zip(
            rng.integers(0, 10000, n), rng.choice(list("ABCDEFGHJKLMNPQR"), n), strict=True
        )
    ]
    return pd.DataFrame({
        "customerID": [f"{i}{k:05d}" for k, i in enumerate(ids)], "SeniorCitizen": senior,
        "tenure": tenure, "Contract": contract, "InternetService": internet,
        "TechSupport": support, "PaymentMethod": payment, "MonthlyCharges": monthly,
        "TotalCharges": total_text, "Churn": np.where(churn, "Yes", "No"),
    })  # fmt: skip


def credit_default(rng: np.random.Generator, n: int) -> pd.DataFrame:
    limit = np.round(np.exp(rng.normal(11.8, 0.7, n)), -3).astype(int)
    age = rng.integers(21, 70, n)
    education = rng.choice([1, 2, 3, 4], n, p=[0.35, 0.47, 0.16, 0.02])
    marriage = rng.choice([1, 2, 3], n, p=[0.45, 0.53, 0.02])
    risk = rng.normal(0, 1, n)
    cols: dict[str, object] = {
        "ID": np.arange(1, n + 1),
        "LIMIT_BAL": limit,
        "SEX": rng.choice([1, 2], n, p=[0.4, 0.6]),
        "EDUCATION": education,
        "MARRIAGE": marriage,
        "AGE": age,
    }
    for month in (1, 2, 3):
        status = np.clip(np.round(risk * 1.1 + rng.normal(0, 0.8, n)), -2, 8).astype(int)
        bill = np.round(limit * np.clip(rng.normal(0.35, 0.3, n), -0.02, 1.0))
        paid = np.round(np.abs(bill) * np.clip(rng.normal(0.12, 0.1, n), 0, 1))
        cols |= {f"PAY_{month}": status, f"BILL_AMT{month}": bill.astype(int),
                 f"PAY_AMT{month}": paid.astype(int)}  # fmt: skip
    logit = 1.2 * risk - 0.000002 * limit - 1.3
    cols["default.payment.next.month"] = (rng.random(n) < _sigmoid(logit)).astype(int)
    return pd.DataFrame(cols)


def land_cover(rng: np.random.Generator, n: int) -> pd.DataFrame:
    classes = ["water", "forest", "grassland", "cropland", "urban"]
    label = rng.choice(classes, n, p=[0.14, 0.27, 0.22, 0.24, 0.13])
    centers = {"water": (20, 30, 15, 5), "forest": (35, 55, 30, 70), "grassland": (55, 75, 50, 50),
               "cropland": (60, 70, 65, 60), "urban": (80, 80, 85, 30)}  # fmt: skip
    bands = np.array([centers[c] for c in label], dtype=float) + rng.normal(0, 9, (n, 4))
    ndvi = (bands[:, 3] - bands[:, 2]) / (bands[:, 3] + bands[:, 2] + 1e-6)
    return pd.DataFrame({
        "tile_id": np.arange(100001, 100001 + n), "blue": bands[:, 0].round(1),
        "green": bands[:, 1].round(1), "red": bands[:, 2].round(1), "nir": bands[:, 3].round(1),
        "ndvi": ndvi.round(4), "elevation_m": np.round(rng.gamma(2.0, 180, n)
                                                       + 150 * (label == "forest")),
        "slope_deg": np.round(rng.gamma(1.5, 4, n), 1),
        "region": rng.choice(["north", "south", "east", "west"], n), "land_cover": label,
    })  # fmt: skip


Generator = Callable[[np.random.Generator, int], pd.DataFrame]

SAMPLES: tuple[tuple[Sample, Generator, int], ...] = (
    (Sample("passengers", "Ship passengers (synthetic, binary)",
            "Who survived? Small data (891 rows): shows repeated CV without a holdout.",
            "Survived", Task.BINARY, 891), passengers, 1912),
    (Sample("house_prices", "House prices (synthetic, regression)",
            "Predict the sale price from size, quality, location and age.",
            "SalePrice", Task.REGRESSION, 2400), house_prices, 1460),
    (Sample("adult_income", "Adult income (synthetic, binary)",
            "Does a person earn over 50K? Census-style categorical data.",
            "income", Task.BINARY, 4000), adult_income, 1994),
    (Sample("telco_churn", "Telco churn (synthetic, binary)",
            "Which customers leave? Includes an ID column and blank totals.",
            "Churn", Task.BINARY, 3500), telco_churn, 7043),
    (Sample("credit_default", "Credit default (synthetic, binary)",
            "Will a card holder default next month? Numeric payment history.",
            "default.payment.next.month", Task.BINARY, 4000), credit_default, 2005),
    (Sample("land_cover", "Land cover (synthetic, multiclass)",
            "Classify map tiles into five land-cover types from spectral bands.",
            "land_cover", Task.MULTICLASS, 2500), land_cover, 846),
)  # fmt: skip


def samples() -> list[Sample]:
    """The sample catalog, in display order."""
    return [s for s, _, _ in SAMPLES]


def sample(sample_id: str) -> Sample:
    for s, _, _ in SAMPLES:
        if s.sample_id == sample_id:
            return s
    raise KeyError(f"unknown sample {sample_id!r}")


def sample_bytes(sample_id: str) -> bytes:
    """The sample's CSV bytes (deterministic: fixed seed, `\\n` line endings)."""
    for s, make, seed in SAMPLES:
        if s.sample_id == sample_id:
            frame = make(np.random.default_rng(seed), s.rows)
            return frame.to_csv(index=False, lineterminator="\n").encode("utf-8")
    raise KeyError(f"unknown sample {sample_id!r}")


def sample_path(sample_id: str, data_dir: Path) -> Path:
    """Write the sample once under `data_dir/samples/` and return its path."""
    target = data_dir / "samples" / sample(sample_id).filename
    if not target.exists():
        target.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        tmp = target.with_suffix(".tmp")
        tmp.write_bytes(sample_bytes(sample_id))
        tmp.replace(target)
    return target


def sha256(sample_id: str) -> str:
    return hashlib.sha256(sample_bytes(sample_id)).hexdigest()
